def test_span_tree_with_event_mappings() -> None:
    handle, _, query = init_memory_tracing("tree")
    trace_id = create_span_tree(
        handle,
        {
            "name": "root",
            "kind": "client",
            "events": [{"name": "with-attrs", "attributes": {"k": "v"}}, "plain"],
            "children": [{"name": "leaf", "error": "boom"}],
        },
    )
    handle.force_flush(5)
    trace = query.get_trace(trace_id)
    assert trace is not None
    root = next(s for s in trace.spans if s.name == "root")
    leaf = next(s for s in trace.spans if s.name == "leaf")
    assert [e.name for e in root.events] == ["with-attrs", "plain"]
    assert root.events[0].attributes == {"k": "v"}
    assert root.kind == "client"
    assert leaf.status.code == "error"
    handle.shutdown()


