def test_get_trace_until_partial_and_missing() -> None:
    handle, _, query = init_memory_tracing("partial")
    ctx = StepContext({}, TracingTarget(handle=handle, query=query), {})
    trace_id = tracing_ops["span"](ctx, {"name": "only"})
    tracing_ops["flush"](ctx, {})
    partial = ctx.resolve(
        tracing_ops["getTraceUntil"](
            ctx, {"traceId": trace_id, "minSpans": 3, "timeoutMs": 50, "intervalMs": 10}
        )
    )
    assert isinstance(partial, Trace)
    assert len(partial.spans) == 1

    class Missing(BaseTraceQueryClient):
        def get_trace(self, trace_id: str) -> Trace | None:
            raise NotFoundError("missing")

    missing_ctx = StepContext({}, TracingTarget(handle=handle, query=Missing()), {})
    with pytest.raises(TimeoutError):
        missing_ctx.resolve(
            tracing_ops["getTraceUntil"](
                missing_ctx, {"traceId": trace_id, "timeoutMs": 30, "intervalMs": 10}
            )
        )
    ctx.close()
    missing_ctx.close()
    handle.shutdown()
